window.openSecurityModal = function() {
  const errMsg = document.getElementById("captcha-error-msg");
  if (errMsg) {
    errMsg.style.display = "none";
    errMsg.innerText = "Security verification failed. Please try again.";
  }
  const modal = document.getElementById("security-modal-overlay");
  if (modal) {
    modal.classList.add("active");
    modal.style.display = "flex";
    modal.style.visibility = "visible";
    modal.style.opacity = "1";
  }
  const revealed = document.getElementById("contact-details-revealed");
  if (revealed) revealed.style.display = "none";

  const container = document.getElementById("cf-turnstile-container");
  if (!container) return;

  container.style.display = "flex";
  container.innerHTML = '<div style="display:flex;align-items:center;gap:0.5rem;color:var(--text-sub);font-size:0.85rem;"><svg width="20" height="20" viewBox="0 0 24 24" style="animation:spin 1s linear infinite;"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="3" fill="none" stroke-dasharray="31.4" stroke-dashoffset="10" stroke-linecap="round"/></svg> Loading Cloudflare Turnstile...</div><style>@keyframes spin{to{transform:rotate(360deg)}}</style>';

  function renderTurnstileWidget() {
    if (!window.turnstile || !container) return;
    container.innerHTML = '';
    try {
      turnstile.render('#cf-turnstile-container', {
        sitekey: '0x4AAAAAAD9nlicfqO7QQsBk',
        theme: document.documentElement.classList.contains('dark') || !document.body.classList.contains('light-theme') ? 'dark' : 'light',
        callback: window.onTurnstileSuccess,
        'error-callback': function() {
          if (errMsg) {
            errMsg.innerText = "Cloudflare verification challenge error. Please try again.";
            errMsg.style.display = "block";
          }
        },
        'expired-callback': function() {
          if (errMsg) {
            errMsg.innerText = "Verification expired. Please complete the challenge again.";
            errMsg.style.display = "block";
          }
        }
      });
    } catch (err) {
      console.warn("Turnstile render error:", err);
      showTurnstileLoadError();
    }
  }

  function showTurnstileLoadError() {
    if (container && (!revealed || revealed.style.display === "none")) {
      container.innerHTML = '<div style="text-align:center; padding: 0.75rem;"><p style="font-size:0.85rem;color:#f87171;margin-bottom:0.6rem;">Security challenge could not be loaded.<br><span style="font-size:0.75rem;color:var(--text-muted);">Please disable ad-blockers or check connection.</span></p><button class="btn btn-outline" style="font-size:0.82rem;padding:0.4rem 0.9rem;" onclick="openSecurityModal()">🔄 Retry Challenge</button></div>';
    }
  }

  if (window.turnstile) {
    renderTurnstileWidget();
  } else {
    let script = document.getElementById("cf-turnstile-api-script");
    if (!script) {
      script = document.createElement("script");
      script.id = "cf-turnstile-api-script";
      script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
      script.async = true;
      script.defer = true;
      script.onload = () => {
        renderTurnstileWidget();
      };
      script.onerror = () => {
        showTurnstileLoadError();
      };
      document.head.appendChild(script);
    } else {
      let checks = 0;
      const poll = setInterval(() => {
        checks++;
        if (window.turnstile) {
          clearInterval(poll);
          renderTurnstileWidget();
        } else if (checks > 25) {
          clearInterval(poll);
          showTurnstileLoadError();
        }
      }, 200);
    }
  }
};

window.closeSecurityModal = function() {
  const modal = document.getElementById("security-modal-overlay");
  if (modal) {
    modal.classList.remove("active");
    modal.style.display = "none";
  }
};

window.onTurnstileSuccess = async function(token) {
  const errMsg = document.getElementById("captcha-error-msg");
  if (errMsg) errMsg.style.display = "none";

  const container = document.getElementById("cf-turnstile-container");
  if (container) {
    container.innerHTML = '<div style="display:flex;align-items:center;gap:0.5rem;color:var(--emerald);font-size:0.85rem;"><svg width="20" height="20" viewBox="0 0 24 24" style="animation:spin 1s linear infinite;"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="3" fill="none" stroke-dasharray="31.4" stroke-dashoffset="10" stroke-linecap="round"/></svg> Authenticating with Cloudflare Gateway...</div>';
  }

  try {
    const res = await fetch(CLOUDFLARE_WORKER_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ turnstileToken: token })
    });

    if (!res.ok) throw new Error("Worker verification rejected: " + res.status);
    const data = await res.json();

    if (data && data.email && data.phone) {
      revealCandidateInfo(data.email, data.phone);
    } else {
      revealCandidateInfo("hello@irfanfahmi.com", "+60 16-243 2023");
    }
  } catch (err) {
    console.error("Secure verification failed:", err);
    if (errMsg) {
      errMsg.innerText = "Gateway verification failed. Please try again.";
      errMsg.style.display = "block";
    }
    if (window.turnstile) {
      try { turnstile.reset('#cf-turnstile-container'); } catch(e){}
    }
    if (container) {
      container.innerHTML = '<button class="btn btn-outline" style="font-size:0.82rem;padding:0.4rem 0.9rem;" onclick="openSecurityModal()">🔄 Re-verify</button>';
    }
  }
};

