/* --- MOBILE APP TAB ROUTER & INTERACTION SYSTEM --- */
const TAB_ALIAS_MAP = {
  'home': 'tab-home',
  'about': 'tab-home',
  'tab-home': 'tab-home',
  'projects': 'tab-projects',
  'tab-projects': 'tab-projects',
  'skills': 'tab-skills',
  'experience': 'tab-skills',
  'exp': 'tab-skills',
  'tab-skills': 'tab-skills',
  'certificates': 'tab-certs',
  'certs': 'tab-certs',
  'tab-certs': 'tab-certs',
  'chat': 'tab-chat',
  'ai': 'tab-chat',
  'tab-chat': 'tab-chat'
};

const TAB_HASH_MAP = {
  'tab-home': '#home',
  'tab-projects': '#projects',
  'tab-skills': '#skills',
  'tab-certs': '#certificates',
  'tab-chat': '#chat'
};

let currentActiveMobileTab = 'tab-home';
let hasUserNavigatedTab = false;

function switchMobileTab(targetTabId, pushHistory = false) {
  const resolvedId = TAB_ALIAS_MAP[String(targetTabId).replace(/^#/, '')] || 'tab-home';
  currentActiveMobileTab = resolvedId;

  if (window.innerWidth <= 768) {
    // 1. Hide all tab views, show target tab view
    document.querySelectorAll('.mobile-tab-view').forEach(view => {
      if (view.id === resolvedId) {
        view.classList.add('active');
        view.style.display = 'block';
      } else {
        view.classList.remove('active');
        view.style.display = 'none';
      }
    });

    // 2. Update dock active state
    document.querySelectorAll('.mobile-bottom-dock .dock-item').forEach(item => {
      const itemTab = item.getAttribute('data-tab');
      if (itemTab === resolvedId) {
        item.classList.add('active');
        item.setAttribute('aria-current', 'page');
      } else {
        item.classList.remove('active');
        item.removeAttribute('aria-current');
      }
    });

    // 3. Scroll view to top instantly
    window.scrollTo({ top: 0, behavior: 'instant' });

    // 4. Special tab triggers
    if (resolvedId === 'tab-certs') {
      if (typeof loadCertRegistry === 'function' && (!CERT_REGISTRY || CERT_REGISTRY.length === 0)) {
        loadCertRegistry();
      }
    } else if (resolvedId === 'tab-chat') {
      if (typeof renderRandomChips === 'function') {
        renderRandomChips();
      }
      if (backendStatus === 'checking' || backendStatus === 'offline') {
        checkBackendStatus();
      }
      // Never auto-focus input on mobile to prevent virtual keyboard from popping up unexpectedly
    }

    // 5. Accessibility: View container tabindex set without stealing software focus on touch
    const activeEl = document.getElementById(resolvedId);
    if (activeEl) {
      activeEl.setAttribute('tabindex', '-1');
    }

    // 6. URL History Sync (prevent back-button 5-step trap)
    const targetHash = TAB_HASH_MAP[resolvedId] || '#home';
    if (window.location.hash !== targetHash) {
      if (pushHistory && hasUserNavigatedTab) {
        history.pushState({ tab: resolvedId }, '', targetHash);
      } else {
        history.replaceState({ tab: resolvedId }, '', targetHash);
      }
      hasUserNavigatedTab = true;
    }
  } else {
    // Desktop: Smooth scroll to section
    const targetHash = TAB_HASH_MAP[resolvedId] || '#home';
    const targetSec = document.querySelector(targetHash);
    if (targetSec) {
      targetSec.scrollIntoView({ behavior: 'smooth' });
    }
  }
}

function handleDockTabClick(e, tabId) {
  if (e) e.preventDefault();
  switchMobileTab(tabId, false);
}

// In-page link interceptor for mobile tabs
document.addEventListener('click', function(e) {
  if (window.innerWidth <= 768) {
    const anchor = e.target.closest('a[href^="#"]');
    if (anchor && !anchor.classList.contains('dock-item')) {
      const href = anchor.getAttribute('href');
      if (href && href.length > 1) {
        const rawId = href.substring(1);
        const mappedTab = TAB_ALIAS_MAP[rawId];
        if (mappedTab) {
          e.preventDefault();
          switchMobileTab(mappedTab, true);
        }
      }
    }
  }
});

function initMobileRouter() {
  const currentHash = window.location.hash;
  if (currentHash && currentHash.length > 1) {
    const raw = currentHash.substring(1);
    const targetTab = TAB_ALIAS_MAP[raw];
    if (targetTab) {
      switchMobileTab(targetTab, false);
      return;
    }
  }
  if (window.innerWidth <= 768) {
    switchMobileTab('tab-home', false);
  }
}

window.addEventListener('hashchange', function() {
  if (window.innerWidth <= 768) {
    const currentHash = window.location.hash;
    const raw = currentHash ? currentHash.substring(1) : 'home';
    const targetTab = TAB_ALIAS_MAP[raw] || 'tab-home';
    if (targetTab !== currentActiveMobileTab) {
      switchMobileTab(targetTab, false);
    }
  }
});

window.addEventListener('popstate', function(e) {
  if (window.innerWidth <= 768 && e.state && e.state.tab) {
    switchMobileTab(e.state.tab, false);
  }
});

let lastWindowWidth = window.innerWidth;
window.addEventListener('resize', function() {
  const currentWidth = window.innerWidth;
  // Ignore vertical-only height resizes caused by mobile virtual keyboard popping up or hiding
  if (currentWidth === lastWindowWidth) return;
  lastWindowWidth = currentWidth;

  if (currentWidth <= 768) {
    switchMobileTab(currentActiveMobileTab, false);
  } else {
    document.querySelectorAll('.mobile-tab-view').forEach(view => {
      view.style.display = '';
    });
  }
}, { passive: true });

function handleChatEnter(e) {
  if (e.key === "Enter") {
    e.preventDefault();
    submitChatMessage();
  }
}

function handleMobileChatEnter(e) {
  if (e.key === "Enter") {
    e.preventDefault();
    submitMobileChatMessage();
  }
}

function submitMobileChatMessage() {
  if (isGeneratingChat) return;
  const mInp = document.getElementById('mobile-chat-user-input');
  if (!mInp) return;
  const val = mInp.value.trim();
  if (!val) return;
  submitChatMessage(val);
}

function sendSuggestedPrompt(text) {
  if (isGeneratingChat || !text) return;
  submitChatMessage(text);
}

window.switchMobileTab = switchMobileTab;
window.handleDockTabClick = handleDockTabClick;
window.handleChatEnter = handleChatEnter;
window.handleMobileChatEnter = handleMobileChatEnter;
window.submitChatMessage = submitChatMessage;
window.submitMobileChatMessage = submitMobileChatMessage;
window.sendSuggestedPrompt = sendSuggestedPrompt;
